import * as AasJsonization from "../src/jsonization";
import * as AasTypes from "../src/types";

test("Color deserializes Red OK", () => {
  const jsonable = "Red";

  const literalOrError = AasJsonization.colorFromJsonable(
    jsonable
  );

  expect(literalOrError.error).toBeNull();
  const parsedLiteral = literalOrError.mustValue();

  expect(parsedLiteral).toStrictEqual(
    AasTypes.Color.Red
  );
});

test("Color deserializes Green OK", () => {
  const jsonable = "Green";

  const literalOrError = AasJsonization.colorFromJsonable(
    jsonable
  );

  expect(literalOrError.error).toBeNull();
  const parsedLiteral = literalOrError.mustValue();

  expect(parsedLiteral).toStrictEqual(
    AasTypes.Color.Green
  );
});

test("Color deserialization fail", () => {
  const jsonable = "invalid-literal";

  const literalOrError = AasJsonization.colorFromJsonable(
    jsonable
  );

  expect(literalOrError.error.message).toStrictEqual(
    "Not a valid string representation of a literal of Color: invalid-literal"
  );
});

